#include <iostream>
#include <ranges>
int main() {
    auto muestras = std::views::iota(10) | std::views::take(3);
    for (int valor : muestras) std::cout << valor << '\n';
}

#include <array>
#include <iostream>
#include <ranges>
struct Sesion { int minutos; };
int main() {
    const std::array sesiones{Sesion{15}, Sesion{25}};
    int total = 0;
    for (int minutos : sesiones | std::views::transform(&Sesion::minutos)) {
        total += minutos;
    }
    std::cout << total << '\n';
}

#include <array>
#include <iostream>
#include <ranges>
int main() {
    std::array valores{2, 4, 8};
    for (int n : valores | std::views::reverse) std::cout << n << '\n';
    std::cout << "Inicio: " << valores.front() << '\n';
}

