#include <iostream>
#include <ranges>
#include <string_view>
int main() {
    auto texto = std::string_view{"HTML,CSS,Java"};
    for (auto parte : texto | std::views::split(',')) {
        for (char letra : parte) std::cout << letra;
        std::cout << '\n';
    }
}

#include <algorithm>
#include <array>
#include <iostream>
#include <iterator>
#include <vector>
int main() {
    const std::array origen{15, 25};
    std::vector<int> destino;
    std::ranges::copy(origen, std::back_inserter(destino));
    std::cout << destino.size() << ' ' << destino.back() << '\n';
}

#include <algorithm>
#include <array>
#include <iostream>
int main() {
    std::array valores{2, 5, 5, 5, 8};
    auto inicio = std::ranges::lower_bound(valores, 5);
    auto final = std::ranges::upper_bound(valores, 5);
    std::cout << final - inicio << '\n';
}

#include <algorithm>
#include <iostream>
#include <vector>
int main() {
    std::vector<int> datos{4, 4, 7, 7, 9};
    auto sobrantes = std::ranges::unique(datos);
    datos.erase(sobrantes.begin(), sobrantes.end());
    for (int n : datos) std::cout << n << '\n';
}

#include <chrono>
#include <iostream>
int main() {
    using namespace std::chrono;
    auto primero = duration_cast<minutes>(seconds{125});
    auto segundo = duration_cast<minutes>(seconds{-125});
    std::cout << primero.count() << ' ' << segundo.count() << '\n';
}

#include <functional>
#include <iostream>
struct Sesion {
    int minutos;
    int ampliar(int extra) const { return minutos + extra; }
};
int main() {
    Sesion sesion{25};
    std::cout << std::invoke(&Sesion::ampliar, sesion, 10)
              << ' ' << std::invoke(&Sesion::minutos, sesion) << '\n';
}
